-- Install the 275/275 reviewed signature-beat contracts from the canonical
-- legacy authoring artifact. The private mapping also fills future local seed
-- inserts, because migrations run before supabase/seed.sql on a clean reset.

create table if not exists private.legacy_signature_beat_doctrine (
  legacy_signature_beat_id integer primary key,
  trigger_contract jsonb not null
    check (public.trigger_contract_is_valid(trigger_contract))
);

revoke all on private.legacy_signature_beat_doctrine from public, anon, authenticated;

insert into private.legacy_signature_beat_doctrine (
  legacy_signature_beat_id,
  trigger_contract
) values
  (1, '{"title":"Caraxes Sortie","condition":"Daemon mounts Caraxes and deliberately enters an active combat, pursuit, or interception scene.","exclusions":["Mounting, approaching or flying Caraxes for transport, escape, ceremony or an inactive patrol does not count without an active combat, pursuit or interception purpose."],"adjudication":{"proxies":"do_not_count","offscreen":"do_not_count","mentions":"do_not_count"},"title_review":{"status":"approved","note":"Caraxes Sortie accurately requires Daemon and Caraxes to enter an active combat, pursuit or interception together."},"basis_claim_ids":["daemon-screen-state","caraxes-screen-state"]}'::jsonb),
  (2, '{"title":"Makes Peace","condition":"Daemon and Rhaenyra explicitly reconcile, forgive one another, or reaffirm that they are acting together.","exclusions":["Sharing a scene, pausing an argument, cooperating under necessity, or another character predicting reconciliation does not count without their explicit reconciliation, forgiveness or reaffirmation."],"adjudication":{"proxies":"do_not_count","offscreen":"do_not_count","mentions":"do_not_count"},"title_review":{"status":"approved","note":"Makes Peace accurately requires an explicit reconciliation, forgiveness or reaffirmed alliance between Daemon and Rhaenyra."},"basis_claim_ids":["daemon-screen-state","rhaenyra-screen-state"]}'::jsonb),
  (3, '{"title":"Defies the Queen","condition":"Daemon knowingly disobeys or circumvents a direct instruction from Rhaenyra.","exclusions":["A pre-existing disagreement, private intent, hesitation, or internal change of mind does not count without the qualifying refusal, rejection, confrontation, defection, overruling, circumvention, or visible disobedience in the episode.","An act performed only by an ally, subordinate, messenger, or other proxy does not count for the named owner.","An off-screen report, third-party mention, dream, vision, memory, prediction, or hypothetical version of the opposition does not count."],"adjudication":{"proxies":"do_not_count","offscreen":"do_not_count","mentions":"do_not_count"},"title_review":{"status":"approved","note":"Each listed title honestly names the direct refusal, rejection, confrontation, defection, overruling, circumvention or visible disobedience required by its preserved audited condition."},"basis_claim_ids":["daemon-screen-state","rhaenyra-screen-state"]}'::jsonb),
  (4, '{"title":"Protects Rhaena","condition":"Daemon takes a concrete action that shields Rhaena from punishment, capture, or immediate physical danger.","exclusions":["Concern, advice, a stated wish, an unacted plan, ordinary proximity, or an action that does not satisfy the preserved protection, rescue, escape, treatment, or intervention threshold does not count.","A coincidental outcome, self-rescue, unrelated attack, or proxy intervention does not count for the named protector unless the preserved condition explicitly names participation in an operation.","An off-screen report, recap, mention, dream, vision, memory, prediction, promotional image, or hypothetical danger or rescue does not count."],"adjudication":{"proxies":"explicit_only","offscreen":"do_not_count","mentions":"do_not_count"},"title_review":{"status":"approved","note":"Each title honestly names a concrete protection, rescue, escape, treatment, or intervention; settlement requires the preserved actor, beneficiary, danger, intent, and causal threshold."},"basis_claim_ids":["daemon-screen-state","rhaena-screen-state"]}'::jsonb),
  (5, '{"title":"Hands Her Over","condition":"Daemon voluntarily surrenders Rhaena to Rhaenyra''s custody or supports a punishment Rhaenyra imposes on her.","exclusions":["An inferred motive, passive outcome, accident, ordinary presence, unacted thought, or choice without every knowledge, opportunity, danger, resistance, priority, or causal prerequisite in the preserved condition does not count.","Words alone do not count unless the preserved condition explicitly makes a proposal, agreement, refusal, acceptance, dismissal, or declaration sufficient; where action is required it must also occur.","A proxy choice, off-screen report, recap, mention, dream, vision, memory, prediction, promotional image, or hypothetical alternative does not count."],"adjudication":{"proxies":"do_not_count","offscreen":"do_not_count","mentions":"do_not_count"},"title_review":{"status":"approved","note":"Each title honestly names a deliberate decision, refusal, bargain, concealment, abandonment, support, or priority choice; settlement requires every preserved knowledge, opportunity, consequence, and action qualifier."},"basis_claim_ids":["daemon-screen-state","rhaena-screen-state","rhaenyra-screen-state"]}'::jsonb),
  (6, '{"title":"Baela Heart-to-Heart","condition":"Daemon and Baela have a private conversation in which either one directly discusses Jace, Rhaena, or their family relationship.","exclusions":["Separate scenes, secondhand descriptions, indirect messages, parallel actions, inferred feelings, or merely sharing a location do not count as the preserved direct interaction.","A proxy, ally, messenger, imagined counterpart, or stand-in does not count for either named participant.","An off-screen report, recap, mention, dream, vision, memory, prediction, promotional image, or hypothetical version of the scene does not count."],"adjudication":{"proxies":"do_not_count","offscreen":"do_not_count","mentions":"do_not_count"},"title_review":{"status":"approved","note":"Each title honestly names a direct two-person conversation, confrontation, reconciliation, forgiveness, argument, or romantic interaction whose exact subject and threshold remain the preserved audited condition."},"basis_claim_ids":["daemon-screen-state","baela-screen-state"]}'::jsonb),
  (7, '{"title":"Faces Aemond","condition":"Daemon and Aemond directly see, address, or attack one another in the present timeline.","exclusions":["Separate scenes, secondhand descriptions, indirect messages, parallel actions, inferred feelings, or merely sharing a location do not count as the preserved direct interaction.","A proxy, ally, messenger, imagined counterpart, or stand-in does not count for either named participant.","An off-screen report, recap, mention, dream, vision, memory, prediction, promotional image, or hypothetical version of the scene does not count."],"adjudication":{"proxies":"do_not_count","offscreen":"do_not_count","mentions":"do_not_count"},"title_review":{"status":"approved","note":"Each title honestly names a direct two-person conversation, confrontation, reconciliation, forgiveness, argument, or romantic interaction whose exact subject and threshold remain the preserved audited condition."},"basis_claim_ids":["daemon-screen-state","aemond-screen-state"]}'::jsonb),
  (8, '{"title":"Orders Dragonfire","condition":"Rhaenyra explicitly orders a dragon or dragonrider to burn an enemy, force, fortification, or named target.","exclusions":["Private intent, implication, hesitation, facial expression, prior attitude, or another character''s paraphrase does not count without the explicit order, warning, statement, request, forgiveness, choice, acknowledgment, threat, recommitment, or other declaration required by the audited condition.","Later compliance, success, harm, or agreement is not required unless the preserved audited condition explicitly includes it; conversely, words alone do not satisfy any action that the condition does require.","An off-screen report, proxy statement, third-party mention, dream, vision, memory, prediction about a different event, or hypothetical version of the declaration does not count."],"adjudication":{"proxies":"do_not_count","offscreen":"do_not_count","mentions":"do_not_count"},"title_review":{"status":"approved","note":"Each listed title honestly names an explicit declaration or decision whose complete qualifying boundary remains the preserved audited condition."},"basis_claim_ids":["rhaenyra-screen-state"]}'::jsonb),
